import {
  colors,
  containers,
  focusRing,
  fontSizes,
  fontWeights,
  fonts,
  letterSpacing,
  lineHeights,
  motion,
  displayVariation,
  spacingUnit,
} from "./tokens.ts";

/** Builds src/app/tokens.css from tokens.ts. Run with `npm run tokens`. */
export function renderTokensCss(): string {
  const lines: string[] = [
    "/* Generated from src/design/tokens.ts by `npm run tokens`. Do not edit by hand. */",
    "",
    ":root {",
    ...Object.entries(colors).map(([name, value]) => `  --${name}: ${value};`),
    `  --focus-ring: ${focusRing.width} solid var(--${focusRing.color});`,
    `  --focus-offset: ${focusRing.offset};`,
    "  color-scheme: dark;",
    "}",
    "",
    "/*",
    " * Tailwind theme. The `initial` lines remove Tailwind's default palette,",
    " * shadows, radii and type scale, so only brand tokens generate classes.",
    " */",
    "@theme inline {",
    "  --color-*: initial;",
    ...Object.keys(colors).map((name) => `  --color-${name}: var(--${name});`),
    "",
    `  --font-*: initial;`,
    ...Object.entries(fonts).map(([name, value]) => `  --font-${name}: ${value};`),
    `  --font-display--font-variation-settings: ${displayVariation};`,
    "",
    "  --text-*: initial;",
    ...Object.entries(fontSizes).flatMap(([name, [size, leading]]) => [
      `  --text-${name}: ${size};`,
      `  --text-${name}--line-height: ${leading};`,
    ]),
    "",
    "  --font-weight-*: initial;",
    ...Object.entries(fontWeights).map(([name, value]) => `  --font-weight-${name}: ${value};`),
    "",
    "  --tracking-*: initial;",
    ...Object.entries(letterSpacing).map(([name, value]) => `  --tracking-${name}: ${value};`),
    "",
    "  --leading-*: initial;",
    ...Object.entries(lineHeights).map(([name, value]) => `  --leading-${name}: ${value};`),
    "",
    `  --spacing: ${spacingUnit};`,
    "",
    "  --container-*: initial;",
    ...Object.entries(containers).map(([name, value]) => `  --container-${name}: ${value};`),
    "",
    "  --radius-*: initial;",
    "  --shadow-*: initial;",
    "  --inset-shadow-*: initial;",
    "  --drop-shadow-*: initial;",
    "  --text-shadow-*: initial;",
    "  --blur-*: initial;",
    "",
    `  --default-transition-duration: ${motion.duration};`,
    `  --default-transition-timing-function: ${motion.easing};`,
    "}",
    "",
  ];
  return lines.join("\n");
}
